package net.nerdsmp.probe;

import net.nerdsmp.paper.metrics.MetricsLedger;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Fictional UI fixture generated by the production aggregation code, never imported into live tracking. */
public final class MetricsPreview {
    public static void main(String[] args) throws Exception {
        long now=System.currentTimeMillis(); LocalDate today=Instant.ofEpochMilli(now).atZone(ZoneOffset.UTC).toLocalDate();
        long started=today.minusDays(100).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
        MetricsLedger ledger=new MetricsLedger(started,180); Random random=new Random(42);
        List<UUID> people=new ArrayList<>(); Map<UUID,Integer> joined=new HashMap<>();
        for(int day=0;day<=100;day++) {
            long start=today.minusDays(100-day).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
            if(start>now)start=now-3_600_000;
            int fresh=3+random.nextInt(4); Set<UUID> newToday=new HashSet<>();
            for(int n=0;n<fresh;n++){UUID id=UUID.nameUUIDFromBytes(("fictional-metrics-"+day+"-"+n).getBytes(java.nio.charset.StandardCharsets.UTF_8));people.add(id);newToday.add(id);joined.put(id,day);}
            int visits=0;
            for(UUID player:people) {
                if(!newToday.contains(player)&&random.nextDouble()>(day-joined.get(player)<8?.45:.14))continue;
                long at=start+visits++*500; ledger.join(player,newToday.contains(player),at,false);
                long duration=(3+random.nextInt(85))*60_000L;
                for(long step=30_000;step<=duration;step+=30_000)ledger.sample(player,at+step,random.nextDouble()>.16,visits%3==0?"MMORPG":"Skyhold");
                ledger.quit(player,at+duration);
                for(String skill:List.of("MINING","FORESTRY","SMITHING","HUNTING","COOKING")) {
                    ledger.counter(player,"xp."+skill,50+random.nextInt(1400),at);ledger.counter(player,"activity."+skill,2+random.nextInt(24),at);
                }
                ledger.counter(null,"xpSource.harvest",500+random.nextInt(1500),at);ledger.counter(null,"xpSource.craft",80+random.nextInt(250),at);
                ledger.counter(player,"kills.custom:gloom_wolfhound",random.nextInt(9),at);ledger.counter(player,"kills.vanilla:zombie",random.nextInt(12),at);
                if(random.nextBoolean()){ledger.counter(player,"player.deaths",1,at);ledger.counter(player,random.nextBoolean()?"death.entity_attack":"death.fall",1,at);}
                if(random.nextDouble()<.5){ledger.counter(player,"quest.accepted",1,at);ledger.counter(player,"quest.completed",1,at);ledger.counter(player,"questComplete.goldenreach_harvest",1,at);}
                if(random.nextDouble()<.2){ledger.counter(player,"expedition.participated",1,at);ledger.counter(null,"expedition.started",1,at);boolean complete=random.nextBoolean();ledger.counter(null,complete?"expedition.completed":"expedition.failed",1,at);if(complete)ledger.counter(null,"expedition.seconds",900,at);}
                ledger.counter(null,"marks.credit.loot.coin_purse",500+random.nextInt(2500),at);ledger.counter(null,"marks.credit.daily.quest",300,at);
                ledger.counter(null,"marks.debit.npc.shop",300+random.nextInt(600),at);ledger.counter(null,"marks.debit.forge.repair",100,at);ledger.counter(null,"marks.transfer.player.pay",200,at);
            }
            for(int step=0;step<=2880;step++) {long at=start+step*30_000L;if(at>now)break;ledger.pulse(at,Math.max(0,visits/5+random.nextInt(10)-5),19+random.nextDouble(),14+random.nextDouble()*22,350+visits*5);}
        }
        var report=ledger.report(now);report.addProperty("saved",now-60_000);report.addProperty("sampleGapMs",0);
        Files.writeString(Path.of(args[0]),new com.google.gson.Gson().toJson(report));
    }
}
